declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
$user=require_login(['admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    if(($_POST['action']??'')==='purge_audit'){
        $eligible=(int)db()->query("SELECT COUNT(*) FROM audit_logs WHERE created_at<DATE_SUB(NOW(),INTERVAL ".AUDIT_RETENTION_MONTHS." MONTH)")->fetchColumn();
        $stmt=db()->prepare("DELETE FROM audit_logs WHERE created_at<DATE_SUB(NOW(),INTERVAL ".AUDIT_RETENTION_MONTHS." MONTH)");$stmt->execute();
        audit((int)$user['id'],'audit_logs_purged','Purged '.$stmt->rowCount().' audit record(s) older than six months');
        set_flash('success',$stmt->rowCount().' eligible audit record(s) permanently purged.');redirect('admin/system.php');
    }elseif(($_POST['action']??'')==='apply_retention'){
        $pdo=db();$removed=['feedback'=>0,'login_attempts'=>0,'notifications'=>0,'submission_logs'=>0,'previews'=>0];
        $pdo->beginTransaction();
        try{
            $stmt=$pdo->prepare("DELETE FROM feedback WHERE submitted_at<DATE_SUB(NOW(),INTERVAL ".FEEDBACK_RETENTION_MONTHS." MONTH)");$stmt->execute();$removed['feedback']=$stmt->rowCount();
            $stmt=$pdo->prepare("DELETE FROM login_attempts WHERE attempted_at<DATE_SUB(NOW(),INTERVAL ".LOGIN_ATTEMPT_RETENTION_DAYS." DAY)");$stmt->execute();$removed['login_attempts']=$stmt->rowCount();
            $stmt=$pdo->prepare("DELETE FROM notifications WHERE created_at<DATE_SUB(NOW(),INTERVAL ".NOTIFICATION_RETENTION_DAYS." DAY)");$stmt->execute();$removed['notifications']=$stmt->rowCount();
            try{$stmt=$pdo->prepare("DELETE FROM public_submission_log WHERE submitted_at<DATE_SUB(NOW(),INTERVAL ".LOGIN_ATTEMPT_RETENTION_DAYS." DAY)");$stmt->execute();$removed['submission_logs']=$stmt->rowCount();}catch(Throwable){}
            $pdo->commit();
        }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
        $previewDir=__DIR__.'/../storage/import_previews';
        if(is_dir($previewDir)){foreach(glob($previewDir.'/preview_*.json')?:[] as $file){if(is_file($file)&&filemtime($file)<time()-(IMPORT_PREVIEW_RETENTION_HOURS*3600)&&@unlink($file))$removed['previews']++;}}
        audit((int)$user['id'],'retention_policy_applied',json_encode($removed));
        set_flash('success','Retention maintenance completed: '.array_sum($removed).' expired record/file(s) removed.');redirect('admin/system.php');
    }
}
$q=trim((string)($_GET['q']??''));$actionFilter=trim((string)($_GET['action_filter']??''));$roleFilter=trim((string)($_GET['role_filter']??''));$validRoles=['admin','office_head','supervisor','office_staff','public'];$where=['1=1'];$params=[];
if($q!==''){$where[]='(a.details LIKE ? OR a.ip_address LIKE ? OR u.full_name LIKE ? OR u.username LIKE ? OR o.name LIKE ? OR o.code LIKE ?)';array_push($params,"%{$q}%","%{$q}%","%{$q}%","%{$q}%","%{$q}%","%{$q}%");}
if($actionFilter!==''){$where[]='a.action=?';$params[]=$actionFilter;}
if(in_array($roleFilter,$validRoles,true)){if($roleFilter==='public')$where[]='a.user_id IS NULL';else{$where[]='u.role=?';$params[]=$roleFilter;}}
