$limit=$p['per_page'];$offset=$p['offset'];
if($exportPdf){if($scope==='all'){$limit=$p['total'];$offset=0;}elseif($scope==='custom'){$offset=($from-1)*$perPage;$limit=($to-$from+1)*$perPage;}else{$offset=($from-1)*$perPage;}}
$stmt=db()->prepare("SELECT a.*,CASE WHEN u.id IS NULL THEN 'Public / System' ELSE CONCAT(u.full_name,' — ',CASE u.role WHEN 'office_head' THEN 'Office Head' WHEN 'office_staff' THEN 'Office Staff' WHEN 'supervisor' THEN 'Supervisor' ELSE 'Admin' END,CASE WHEN o.code IS NULL THEN '' ELSE CONCAT(' — ',o.code) END) END full_name,u.username,u.role,o.name office_name,o.code office_code FROM audit_logs a{$auditJoins}WHERE {$whereSql} ORDER BY a.created_at DESC LIMIT ".max(1,$limit).' OFFSET '.$offset);$stmt->execute($params);$logs=$stmt->fetchAll();
$eligiblePurge=(int)db()->query("SELECT COUNT(*) FROM audit_logs WHERE created_at<DATE_SUB(NOW(),INTERVAL ".AUDIT_RETENTION_MONTHS." MONTH)")->fetchColumn();
$modelFile=__DIR__.'/../ml/models/svm_sentiment.joblib';$metricsFile=__DIR__.'/../ml/models/model_metrics.json';$metrics=is_file($metricsFile)?json_decode((string)file_get_contents($metricsFile),true):null;$health=predict_sentiment('Mabilis at maayos ang serbisyo.');$metricSamples=(int)($metrics['unique_samples']??$metrics['sample_count']??0);$metricAccuracy=(float)($metrics['final_test_accuracy']??$metrics['accuracy']??0);if($metrics){$metrics['unique_samples']=$metricSamples;$metrics['final_test_accuracy']=$metricAccuracy;}
$counts=['active_offices'=>(int)db()->query("SELECT COUNT(*) FROM offices WHERE status='active'")->fetchColumn(),'reviews'=>(int)db()->query("SELECT COUNT(*) FROM feedback WHERE review_status='needs_review' AND is_void=0")->fetchColumn(),'training'=>(int)db()->query('SELECT COUNT(*) FROM training_candidates')->fetchColumn(),'locked'=>(int)db()->query('SELECT COUNT(*) FROM users WHERE locked_until>NOW()')->fetchColumn()];$actions=db()->query('SELECT DISTINCT action FROM audit_logs ORDER BY action')->fetchAll(PDO::FETCH_COLUMN);
render_dashboard_start($exportPdf?'Ulat ng Audit Log':'System & Audit','system');page_header('System Health & Audit','Makikita rito ang mga aktibidad ng Admin, Office Head, Supervisor, Staff, at public users.',$exportPdf?'':'<button type="button" class="btn" data-modal-open="backup-modal">Gumawa ng Encrypted Backup</button><button type="button" class="btn secondary" data-modal-open="retention-modal">Retention Policy</button>');
?>
